+/// Inverts a nonzero canonical integer modulo n with the binary extended
+/// Euclidean algorithm. The result is canonical.
+#[inline]
+fn invert_canonical(a: [u64; 4]) -> [u64; 4] {
+    const ONE: [u64; 4] = [1, 0, 0, 0];
+
+    let mut u = a;
+    let mut v = MODULUS;
+    let mut x1 = ONE;
+    let mut x2 = [0u64; 4];
+
+    while u != ONE && v != ONE {
+        while u[0] & 1 == 0 {
+            u = shr1(u, 0);
+            x1 = half_mod(x1);
+        }
+        while v[0] & 1 == 0 {
+            v = shr1(v, 0);
+            x2 = half_mod(x2);
+        }
+
+        let (difference, borrow) = sub_limbs(u, v);
+        if borrow == 0 {
+            u = difference;
+            x1 = sub_mod(x1, x2);
+        } else {
+            v = sub_limbs(v, u).0;
+            x2 = sub_mod(x2, x1);
+        }
+    }
+
+    if u == ONE {
+        x1
+    } else {
+        x2
+    }
+}
+
+#[inline(always)]
+fn shr1(a: [u64; 4], top: u64) -> [u64; 4] {
+    [
+        (a[0] >> 1) | (a[1] << 63),
+        (a[1] >> 1) | (a[2] << 63),
+        (a[2] >> 1) | (a[3] << 63),
+        (a[3] >> 1) | (top << 63),
+    ]
+}
+
+#[inline(always)]
+fn half_mod(a: [u64; 4]) -> [u64; 4] {
+    if a[0] & 1 == 0 {
+        shr1(a, 0)
+    } else {
+        let (sum, carry) = add_limbs(a, MODULUS);
+        shr1(sum, carry)
+    }
+}
+
+#[inline(always)]
+fn sub_mod(a: [u64; 4], b: [u64; 4]) -> [u64; 4] {
+    let (difference, borrow) = sub_limbs(a, b);
+    if borrow == 0 {
+        difference
+    } else {
+        add_limbs(difference, MODULUS).0
+    }
+}

